// Protect LaTeX from Markdown emphasis and keep partial streamed equations literal.
(() => {
 const token=/(`[^`]*`|\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)|(?<!\\)\$(?!\$)[^\n$]+?\$)/g;
 function inline(parent,text,plain){let last=0;for(const match of text.matchAll(token)){plain(parent,text.slice(last,match.index));const raw=match[0];if(raw.startsWith('`'))plain(parent,raw);else{const display=raw.startsWith('$$')||raw.startsWith('\\['),size=raw.startsWith('$')&&!display?1:2;const span=document.createElement('span');span.className=display?'chat-equation':'chat-inline-equation';try{if(!window.katex)throw Error();window.katex.render(raw.slice(size,-size),span,{displayMode:display,throwOnError:true,trust:false,strict:'ignore',maxExpand:200,maxSize:10,output:'htmlAndMathml'});}catch{span.textContent=raw;span.className+=' chat-math-pending';}parent.append(span);}last=match.index+raw.length;}const rest=text.slice(last);const start=rest.search(/\\[\[(]|\$/);if(start>=0){plain(parent,rest.slice(0,start));const pending=document.createElement('span');pending.className='chat-math-pending';pending.textContent=rest.slice(start);parent.append(pending);}else plain(parent,rest);}
 function lines(text){const result=[];let fenced=false,buffer='',close='';for(const line of text.split('\n')){if(!close&&/^```/.test(line)){fenced=!fenced;result.push(line);continue;}if(fenced){result.push(line);continue;}if(close){buffer+='\n'+line;if(line.includes(close)){result.push(buffer);buffer='';close='';}continue;}const match=line.match(/\$\$|\\\[/);if(match){const end=match[0]==='$$'?'$$':'\\]';if(!line.slice(match.index+match[0].length).includes(end)){buffer=line;close=end;continue;}}result.push(line);}if(buffer)result.push(buffer);return result;}
 window.AssistantMath={inline,lines};
})();
